export type TrackingCounts = { attempted: number; sent: number; delivered: number; read: number; quoted: number;
    declined: number; clarifying: number; failed: number; awaiting: number; noResponse: number };
export type TimelineEvent = { key: string; at: string; label: string };
export type TrackingQuote = { id: string; price: string; originalPrice: string | null; priceBasis: string | null;
    priceValidity: string | null; priceValidUntil: string | null; priceExpired: boolean | null; totalMoq: number | null;
    moqPerColour: number | null; leadDays: number; sampleAvailability: string | null; sampleYardage: number | null;
    sampleLeadDays: number | null; samplingPrice: number | null; remarks: string | null; approvalStatus: string;
    submittedAt: string; submittedAtLabel: string; revision: number; source: string; dispatchLocation: string | null };
export type DispatchLog = {id:string;kind:string;status:string;requestedAt:string;sentAt:string|null;deliveredAt:string|null;readAt:string|null;failureCode:string|null};
export type TrackingSupplier = { dispatchLogs?: DispatchLog[]; resendBlockedReason?: string|null; consentStatus: string; dispatchChannel: string; declineReason: string|null; id: string; supplierId: string; supplierName: string; sourceType: string; sourceId: string;
    matchStatus: string; notificationStatus: string; deliveryStatus: string; responseStatus: string;
    rawWhatsAppStatus: string | null; eligible: boolean; eligibilityReason: string; sentAt: string | null;
    deliveredAt: string | null; readAt: string | null; deadline: string | null; deadlinePassed: boolean;
    reminderCount: number; failureCode: string | null; quote: TrackingQuote | null;
    timeline: TimelineEvent[]; unavailableEvents: string[] };
export type TrackingListItem = { id: string; rfqNumber: string; fabricName: string; quantity: number; createdAt: string;
    recordedStatus: string; overallStatus: string; overallTone: string; matchedSuppliers: number; eligibleSuppliers: number;
    matchCount: number; counts: TrackingCounts };
export type TrackingSummary = TrackingCounts & { inquiries: number };
export type TrackingList = { rows: TrackingListItem[]; summary: TrackingSummary; total: number; page: number; pageSize: number; asOf: string };
export type TrackingDetail = { lifecycle: Array<{key:string;label:string;recorded:boolean;at:string|null}>; inquiry: Omit<TrackingListItem, "eligibleSuppliers" | "matchedSuppliers" | "matchCount" | "counts">;
    suppliers: TrackingSupplier[]; totalMatches: number; page: number; pageSize: number; asOf: string };

